INSERT INTO `update_log` VALUES (2,'新增','账户管理 · 学生列表新增学号筛选，支持姓名 / 学号 / 用户名 / 班级 / 手机号 / 状态的模糊匹配。','2026-10-12 13:10:45'),(3,'新增','学生列表与已排课程列表加入前端分页（每页 20 条）与搜索，大数据量下更流畅。','2026-10-12 13:10:45'),(4,'优化','全部下拉菜单改为自绘组件：选项样式美化，展开 / 收起带过渡动画与箭头旋转。','2026-10-12 13:10:45'),(5,'优化','筛选栏的下拉框与日期框统一为定长宽度，排列更整齐。','2026-10-12 13:10:45'),(6,'优化','上课时间段改为自定义时 / 分选择，个位数字自动补 0。','2026-10-12 13:10:45'),(7,'修复','修复下拉框滚轮滚动时面板意外消失的问题。','2026-10-12 13:10:45'),(8,'修复','日期选择框支持点击整框弹出原生选择器。','2026-10-12 13:10:45'),(9,'修复','修复筛选后滚动条消失导致页面盒子被拉伸的抖动问题。','2026-10-12 13:10:45'),(10,'修复','修复课堂点名「音色」文字与下拉挤在同一列、学生姓名被迫换行的问题。','2026-10-12 13:10:45'),(16,'新增','创建课程支持「重复课程」：可在日期区间内，同教师 / 同班级 / 同时间段连续多天创建。','2026-10-12 00:00:00'),(17,'新增','「跨站签到同步」上线：局域网内多套签到软件之间自动互推 / 互拉签到记录，不直连对方数据库，按统一契约对接接口即可互通。','2026-10-14 10:28:25'),(18,'新增','学生端课程卡片与「签到记录」新增「已在其他网站签到」状态，并标明该条记录来自哪个网站。','2026-10-14 10:28:25'),(19,'新增','教师端点名名册新增「来源」列与「已在其他网站签到」状态；异地有效签到计入实到，并在出勤状态统计中单独成类。','2026-10-14 10:28:25'),(20,'新增','签到前新增跨站查重：自动向其他网站校验同一学生是否已签，命中时拦截重复签到并提示来源网站。','2026-10-14 10:28:25'),(21,'新增','管理后台新增「跨站同步」页：展示各站点连通性、同步进度、发送队列与跨站冲突，支持手动重试与手动对账。','2026-10-14 10:28:25'),(22,'新增','新增跨站冲突自动对账：同一门课出现多站签到时，按签到时间最早者判定有效，冲突记录留档供管理员裁决。','2026-10-14 10:28:25'),(23,'新增','新增《跨站签到数据同步对接契约文档》，含事件格式、对齐键算法、鉴权方式与接口定义，可直接提供给其他签到软件的开发者。','2026-10-14 10:28:25'),(24,'优化','签到实时跨站校验采用单站短超时 + 结果缓存：对方系统不可用时自动放行，保证签到主流程不被拖慢。','2026-10-14 10:28:25'),(25,'新增','跨站同步新增「时段档」字段与归一化：把课程时间段统一归为上午 / 下午两档，可直接适配只区分上午场 / 下午场的对端数据库。','2026-10-14 11:51:35'),(26,'优化','跨站同步对齐键由五段简化为四段（学号｜班级键｜日期｜时段档），并新增班级名归一化与签到状态别名映射，接收方按班级 / 日期 / 时段自动反查本地课程补齐课程名。','2026-10-14 11:51:35'),(27,'优化','后端代码按功能模块重组：拆分为 core（公共基础）/ api（接口蓝图）/ sync（跨站同步）三个包，统一调整模块导入路径；对外接口地址与前端调用方式保持不变。','2026-10-14 11:51:35'),(28,'修复','修复「跨站同步」对端异常提示出现乱码的问题：对端地址不是 Web 服务（如误填数据库端口）时不再回带二进制报文，改为可读的中文提示并给出排查方向。','2026-10-14 11:51:35'),(29,'优化','「跨站同步」页面展示优化：对端离线原因改为带图标的逐条提示，同步进度区分「未同步」状态，在线状态点增加呼吸动效。','2026-10-14 11:51:35'),(30,'新增','「跨站同步」页新增「连接对端」按钮：进入该页自动开始连接对端，30 秒内每 5 秒重试一次并实时显示已连接秒数；30 秒仍未连通则自动取消，需再次点击。','2026-10-14 14:47:32'),(31,'优化','「跨站同步」改为按需触发：取消每 20 秒的定时轮询，仅在本站有学生签到、收到对方推送或管理员手动触发时同步一轮，不再对不可达的对端反复空跑，减少无效请求与日志噪音。','2026-10-14 14:47:32'),(32,'优化','「跨站同步」页顶部排版调整：原「本站标识」卡片改为工具栏左侧的一行站点信息，立即同步 / 执行对账 / 连接对端 / 刷新等操作按钮统一移到右侧。','2026-10-14 14:47:32'),(33,'修复','修复学生端「签到记录」在所选日期没有签到记录时接口报错的问题。','2026-10-14 14:47:32'),(34,'修复','修复教师端「签到名册」在查看点名统计时接口报错的问题。','2026-10-14 14:47:32'),(35,'新增','「跨站同步」冲突列表支持批量处理：可一键裁决或忽略全部待处理冲突，也支持按所选条目批量处理。','2026-10-15 14:21:59'),(36,'优化','「跨站同步」冲突列表新增按状态与关键词筛选，并同时显示当前筛选结果条数与全局待处理冲突总数。','2026-10-15 14:21:59'),(37,'优化','「跨站同步」冲突工具栏排版调整：批量按钮移至左侧并预留占位，切换筛选状态时整体布局不再跳动。','2026-10-15 14:21:59'),(38,'优化','控制台日志按状态码与级别整行着色（401 粉色、INFO 白色、WARN 黄色、ERROR 红色、爬虫标记洋红色）；仅在交互式终端生效，写入文件的日志保持纯文本。','2026-10-15 14:21:59'),(39,'优化','后端跨站读路径统一口径：签到进度、统计分析、学生签到明细共用同一套「有效跨站签到」判定，消除三处重复的查询逻辑，避免口径不一致。','2026-10-15 14:21:59'),(40,'优化','后端只读查询统一改用游标上下文管理器，自动关闭游标并归还连接，减少连接与游标泄漏。','2026-10-15 14:21:59'),(41,'优化','前端抽出公共的错误提示与时间格式化工具，三个工作台不再各自维护重复实现。','2026-10-15 14:21:59'),(42,'修复','修复「跨站同步」冲突列表「落败记录」列恒显示为「-」的问题：原先未解析多条落败记录。','2026-10-15 14:21:59'),(43,'修复','修复冲突裁决 / 忽略后同一冲突被反复重新登记为待处理的问题：去重改为按对齐键 + 胜出记录 ID 判定，不再只比对待处理状态。','2026-10-15 14:21:59'),(44,'修复','修复跨站同步的「回声重复」：本站签到推送给对端后又被拉回，导致同一签到重复入库、本站签到被误显示为「已在其他网站签到」；现增加回声检测，并规定同一秒签到本站优先。','2026-10-15 14:21:59'),(45,'修复','修复教师端「签到进度」与「统计分析」不统计异地有效签到的问题：异地签到现与本站签到合并按学生去重计数。','2026-10-15 14:21:59'),(46,'修复','修复教师端「统计分析」数字与实际不符的问题：原查询遗漏班级字段，导致异地签到被整体过滤。','2026-10-15 14:21:59');
/*!40000 ALTER TABLE `update_log` ENABLE KEYS */;
UNLOCK TABLES;

